from pathlib import Path
import re, subprocess, tempfile

p=Path('index.html')
s=p.read_text(encoding='utf-8')

def once(old,new,label):
    global s
    n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected 1 exact match, got {n}')
    s=s.replace(old,new,1)

def sub(pattern,repl,label,flags=re.S):
    global s
    s2,n=re.subn(pattern,repl,s,count=1,flags=flags)
    if n!=1: raise SystemExit(f'{label}: expected 1 regex match, got {n}')
    s=s2

schema3="db.version(3).stores({providers:'++id,name,category,document',services:'++id,providerId,category,reference,serviceDate,dueDate,status,recurrenceId',receipts:'++id,number,date,providerName,category',settings:'key',meta:'key',recurrences:'++id,providerId,category,active',logs:'++id,at,type,title,detail,role'});"
schema4=schema3+"\ndb.version(4).stores({providers:'++id,name,category,document',services:'++id,providerId,category,reference,serviceDate,dueDate,status,recurrenceId',receipts:'++id,number,date,providerName,category',settings:'key',meta:'key',recurrences:'++id,providerId,category,active',logs:'++id,at,type,title,detail,role',payments:'++id,serviceId,providerId,date,method'});"
once(schema3,schema4,'schema v4')
once("providers:[],services:[],receipts:[],recurrences:[],logs:[],receiptSeqValue:0", "providers:[],services:[],receipts:[],recurrences:[],payments:[],logs:[],receiptSeqValue:0", 'payments state')

load_audit="""async load(){this.providers=await db.providers.toArray();this.services=await db.services.toArray();this.receipts=await db.receipts.toArray();this.recurrences=await db.recurrences.toArray();this.payments=await db.payments.toArray();this.logs=(await db.logs.orderBy('at').reverse().limit(30).toArray());let migrated=await this.ensurePaymentLedger();if(migrated)this.payments=await db.payments.toArray();let meta=await db.meta.get('receiptSeq');this.receiptSeqValue=Number(meta?.value||0);if(!this.receiptSeqInput)this.receiptSeqInput=this.nextReceiptNumber();this.after();this.auditDataIntegrity()},
  async ensurePaymentLedger(){let created=0;for(const s of this.services){let paid=Number(s.paidValue||0);if(paid<=0)continue;let existing=this.payments.filter(p=>Number(p.serviceId)===Number(s.id));if(existing.length)continue;let rs=this.receipts.filter(r=>Number(r.serviceId)===Number(s.id)).sort((a,b)=>Number(a.id||0)-Number(b.id||0)),known=0;for(const r of rs){let amount=Number(r.total||0);if(amount<=0)continue;await db.payments.add({serviceId:s.id,providerId:s.providerId,date:r.paymentDate||r.date||s.paymentDate||s.serviceDate||this.today(),amount,method:r.paymentMethod||s.paymentMethod||'Não informado',receiptId:r.id,source:'receipt-migration',createdAt:new Date().toISOString()});known+=amount;created++}let residual=Math.max(0,paid-known);if(residual>0.009){await db.payments.add({serviceId:s.id,providerId:s.providerId,date:s.paymentDate||s.serviceDate||this.today(),amount:residual,method:s.paymentMethod||'Não informado',receiptId:null,source:'service-migration',createdAt:new Date().toISOString()});created++}}if(created){await db.meta.put({key:'paymentsLedgerV1',value:{created,at:new Date().toISOString()}});console.info('[ReciboCondo] Histórico de pagamentos reconstruído:',created)}return created},
  auditDataIntegrity(){let issues=[],providerIds=new Set(this.providers.map(p=>Number(p.id))),serviceIds=new Set(this.services.map(s=>Number(s.id))),modernReceipts=this.receipts.filter(r=>r.source!=='Excel legado'),records=this.providers.length+this.services.length+this.receipts.length+this.recurrences.length+this.payments.length;for(const s of this.services){if(s.providerId!=null&&s.providerId!==''&&!providerIds.has(Number(s.providerId)))issues.push('Lançamento '+(s.id||'?')+' aponta para prestador inexistente.')}for(const r of this.receipts){if(r.serviceId!=null&&r.serviceId!==''&&!serviceIds.has(Number(r.serviceId)))issues.push('Recibo '+(r.number||r.id||'?')+' aponta para lançamento inexistente.');if(r.providerId!=null&&r.providerId!==''&&!providerIds.has(Number(r.providerId)))issues.push('Recibo '+(r.number||r.id||'?')+' aponta para prestador inexistente.')}for(const p of this.payments){if(p.serviceId!=null&&!serviceIds.has(Number(p.serviceId)))issues.push('Pagamento '+(p.id||'?')+' aponta para lançamento inexistente.');if(p.providerId!=null&&!providerIds.has(Number(p.providerId)))issues.push('Pagamento '+(p.id||'?')+' aponta para prestador inexistente.')}let seen=new Set();for(const r of modernReceipts){let n=String(r.number||'').replace(/\\D/g,'');if(!n)continue;if(seen.has(n))issues.push('Número de recibo duplicado: '+String(r.number||n)+'.');seen.add(n)}for(const s of this.services){let linked=modernReceipts.filter(r=>Number(r.serviceId)===Number(s.id)),issued=linked.reduce((a,r)=>a+Number(r.total||0),0),paid=Number(s.paidValue||0),ledger=this.payments.filter(p=>Number(p.serviceId)===Number(s.id)).reduce((a,p)=>a+Number(p.amount||0),0);if(linked.length&&issued>paid+0.009)issues.push('Recibos do lançamento '+(s.id||'?')+' somam '+this.money(issued)+' acima do pago '+this.money(paid)+'.');if(Math.abs(ledger-paid)>0.009)issues.push('Histórico de pagamentos do lançamento '+(s.id||'?')+' soma '+this.money(ledger)+' mas o acumulado é '+this.money(paid)+'.')}let condo=String(this.settings?.condoName||'').trim(),manager=String(this.settings?.manager||'').trim();if(records>0&&(!condo||!manager))issues.push('Há dados operacionais, mas os dados principais do condomínio estão incompletos.');let max=this.receiptMaxNumber();if(Number(this.receiptSeqValue||0)<max)issues.push('Sequência gravada está atrás do maior recibo; o próximo número continua protegido pelo maior recibo existente.');this.integrityIssues=issues;if(!issues.length)return;let signature=issues.join('|'),key='rc_integrity_warning_signature';if(sessionStorage.getItem(key)===signature)return;sessionStorage.setItem(key,signature);console.warn('[ReciboCondo] Auditoria de integridade:',issues);this.toast('Vigia de integridade encontrou '+issues.length+' alerta(s). Nenhum dado foi alterado.','warning')},
  """
sub(r"async load\(\)\{.*?\},auditDataIntegrity\(\)\{.*?\},\n  (?=get isViewer)",load_audit,'load/audit')

sub(r"get yearlyPaymentRows\(\)\{.*?\},\n  (?=get dashboardCards)","get yearlyPaymentRows(){let y=String(this.dashboardYear||new Date().getFullYear());return this.payments.filter(p=>String(p.date||'').startsWith(y)).map(p=>{let svc=this.services.find(s=>Number(s.id)===Number(p.serviceId));return{providerId:p.providerId??svc?.providerId,category:svc?.category||'Outros',paymentDate:p.date,total:Number(p.amount||0),method:p.method||''}})},\n  ",'yearly payment rows')

report_detail="""get reportDetailRows(){let rows=[],inPeriod=d=>(!this.report.from||String(d||'')>=this.report.from)&&(!this.report.to||String(d||'')<=this.report.to),services=this.services.filter(s=>(this.report.category==='todas'||s.category===this.report.category)&&(this.report.status==='todos'||s.status===this.report.status));for(const s of services){let ps=this.payments.filter(p=>Number(p.serviceId)===Number(s.id)).sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||Number(a.id||0)-Number(b.id||0));if(ps.length){for(const p of ps){if(!inPeriod(p.date))continue;let r=p.receiptId?this.receipts.find(x=>Number(x.id)===Number(p.receiptId)):null;rows.push({...s,reportKey:'p-'+p.id,receiptNumber:r?.number||'PENDENTE',paymentDate:p.date||'',description:r?.description||s.description,reportValue:Number(p.amount||0),paymentMethod:p.method||r?.paymentMethod||s.paymentMethod||''})}}else if(inPeriod(s.serviceDate))rows.push({...s,reportKey:'s-'+s.id,receiptNumber:'-',paymentDate:'',description:s.description,reportValue:0,paymentMethod:''})}return rows.sort((a,b)=>String(a.paymentDate||a.serviceDate||'').localeCompare(String(b.paymentDate||b.serviceDate||''))||String(a.receiptNumber||'').localeCompare(String(b.receiptNumber||'')))},"""
sub(r"get reportDetailRows\(\)\{.*?\},(?=get reportTotals)",report_detail,'report detail')

sub(r"backupStats\(\)\{.*?\},(?=backupDays)","backupStats(){let records=this.providers.length+this.services.length+this.receipts.length+this.recurrences.length+this.payments.length;return{records,providers:this.providers.length,services:this.services.length,receipts:this.receipts.length,recurrences:this.recurrences.length,payments:this.payments.length}},",'backup stats')

save_service="""async saveService(){if(this.isViewer)return;let paid=Number(this.serviceForm.paidValue||0),amount=Number(this.serviceForm.amount||0);if(!Number.isFinite(amount)||amount<=0)return this.toast('Informe um valor de serviço maior que zero.','warning');if(!Number.isFinite(paid)||paid<0)return this.toast('Informe um valor pago válido.','warning');if(paid>amount+0.000001)return this.toast('O valor pago não pode ser maior que o valor do serviço.','warning');let status=paid<=0?'Pendente':(paid>=amount?'Pago':'Parcial'),d={...this.serviceForm,providerId:Number(this.serviceForm.providerId),amount,paidValue:paid,status,paymentDate:paid>0?(this.serviceForm.paymentDate||this.today()):'',paymentMethod:paid>0?(this.serviceForm.paymentMethod||'Não informado'):''};await db.transaction('rw',db.services,db.payments,async()=>{let id=await db.services.add(d);if(paid>0)await db.payments.add({serviceId:id,providerId:d.providerId,date:d.paymentDate,amount:paid,method:d.paymentMethod,receiptId:null,source:'initial',createdAt:new Date().toISOString()})});await this.logAction('service','Lançamento salvo',this.providerName(d.providerId)+' • '+d.category+' • '+this.money(d.amount||0));this.serviceForm={...this.serviceForm,amount:0,location:'',description:'',paymentDate:'',paymentMethod:'',paidValue:0};await this.load();this.toast('Lançamento salvo')},"""
sub(r"async saveService\(\)\{.*?\},(?=clearServiceFilters)",save_service,'save service')

remove_payment="""async removePaymentInternal(id){let s=this.services.find(x=>Number(x.id)===Number(id));if(!s)return;let linked=this.receipts.filter(r=>Number(r.serviceId)===Number(id));await db.transaction('rw',db.receipts,db.services,db.payments,async()=>{for(const r of linked)await db.receipts.delete(r.id);await db.payments.where('serviceId').equals(id).delete();await db.services.update(id,{paidValue:0,paymentDate:'',paymentMethod:'',status:'Pendente'})});for(const r of linked)await this.logAction('delete','Recibo removido por exclusão de pagamento','Nº '+r.number+' • '+(r.providerName||this.providerName(s.providerId)));await this.logAction('delete','Pagamentos excluídos; lançamento mantido',this.providerName(s.providerId)+' • '+this.money(s.paidValue||0));await this.load()},
  """
sub(r"async removePaymentInternal\(id\)\{.*?\},\n  (?=pay\(s\))",remove_payment,'remove payments')

save_payment="""async savePayment(){if(this.isViewer)return;let s=this.paymentTarget,value=Number(this.payment.value||0),paymentDate=this.payment.date||this.today(),method=this.payment.method||'Não informado',remaining=Math.max(0,Number(s.amount||0)-Number(s.paidValue||0));if(value<=0)return this.toast('Informe um valor de pagamento maior que zero.','warning');if(value>remaining+0.000001)return this.toast('O pagamento não pode ser maior que o saldo pendente de '+this.money(remaining)+'.','warning');let paid=Number(s.paidValue||0)+value,status=paid>=Number(s.amount)?'Pago':'Parcial';await db.transaction('rw',db.services,db.payments,async()=>{await db.payments.add({serviceId:s.id,providerId:s.providerId,date:paymentDate,amount:value,method,receiptId:null,source:'manual',createdAt:new Date().toISOString()});await db.services.update(s.id,{paidValue:paid,paymentDate,paymentMethod:method,status})});await this.logAction('payment','Pagamento registrado',this.providerName(s.providerId)+' • '+this.money(value)+' • '+method);this.payModal=false;await this.load();this.toast(status==='Pago'?'Pagamento registrado. Lançamento quitado.':'Pagamento parcial registrado. Saldo restante: '+this.money(Math.max(0,Number(s.amount||0)-paid)))},"""
sub(r"async savePayment\(\)\{.*?\},(?=prepareReceipt)",save_payment,'save payment')

issue="""async issueReceipt(){if(this.isViewer)return;let s=this.services.find(x=>Number(x.id)===Number(this.receiptServiceId));if(!s)return this.toast('Selecione um lançamento.','warning');let linked=this.receipts.filter(r=>Number(r.serviceId)===Number(s.id)),issued=linked.reduce((a,r)=>a+Number(r.total||0),0),pending=Math.max(0,Number(s.paidValue||0)-issued);if(pending<=0)return this.toast('Todos os pagamentos registrados deste lançamento já possuem recibo.','warning');let candidates=this.payments.filter(p=>Number(p.serviceId)===Number(s.id)&&!p.receiptId).sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||Number(a.id||0)-Number(b.id||0)),payment=candidates[0]||null;if(payment&&Number(payment.amount||0)>pending+0.009)return this.toast('O histórico deste pagamento está acima do saldo disponível para recibo. Verifique a integridade antes de emitir.','warning');let receiptTotal=payment?Number(payment.amount||0):pending,paymentDate=payment?.date||s.paymentDate||this.today(),paymentMethod=payment?.method||s.paymentMethod||'Não informado',desc=String(s.description||'').replace(/(\\bparcela\\s+)(\\d+)\\s*\\/\\s*(\\d+)/i,(m,prefix,current,total)=>prefix+String(linked.length+1).padStart(current.length,'0')+'/'+total),p=this.providers.find(x=>Number(x.id)===Number(s.providerId))||{},r=null;await db.transaction('rw',db.meta,db.receipts,db.payments,async()=>{let meta=await db.meta.get('receiptSeq'),next=Math.max(Number(meta?.value||0),this.receiptMaxNumber())+1;r={number:String(next).padStart(6,'0'),date:this.today(),paymentDate,providerId:p.id,providerName:p.name||'Prestador não informado',document:p.document||'',category:s.category,reference:s.reference,description:desc,total:receiptTotal,paymentMethod,location:s.location,serviceId:s.id,paymentId:payment?.id||null,manager:this.settings.manager,condoName:this.settings.condoName,condoCnpj:this.settings.cnpj||'',condoAddress:this.settings.address||''};await db.meta.put({key:'receiptSeq',value:next});let id=await db.receipts.add(r);r.id=id;if(payment)await db.payments.update(payment.id,{receiptId:id})});this.currentReceipt=r;await this.logAction('receipt','Recibo emitido','Nº '+r.number+' • '+r.providerName+' • '+this.money(r.total||0));await this.load();this.toast('Recibo nº '+r.number+' emitido no valor de '+this.money(r.total||0)+'.')},"""
sub(r"async issueReceipt\(\)\{.*?\},(?=printReceipt)",issue,'issue receipt')

remove_receipt="""async removeReceiptInternal(id){let r=this.receipts.find(x=>Number(x.id)===Number(id));if(!r)return;let linked=this.receipts.filter(x=>Number(x.serviceId)===Number(r.serviceId)).sort((a,b)=>Number(b.id||0)-Number(a.id||0)),latest=linked[0];if(latest&&Number(latest.id)!==Number(r.id))return this.toast('Para preservar a data e a forma de pagamento das parcelas, somente o recibo mais recente deste lançamento pode ser excluído e reemitido.','warning');await db.transaction('rw',db.receipts,db.payments,async()=>{await db.receipts.delete(id);let ps=this.payments.filter(p=>Number(p.receiptId)===Number(id));for(const p of ps)await db.payments.update(p.id,{receiptId:null})});if(this.currentReceipt&&Number(this.currentReceipt.id)===Number(id))this.currentReceipt=null;await this.logAction('delete','Recibo excluído',r?('Nº '+r.number+' • '+r.providerName):('ID '+id));await this.load()},
  """
sub(r"async removeReceiptInternal\(id\)\{.*?\},\n  (?=printReport)",remove_receipt,'remove receipt')

backup="""async backup(){let now=new Date().toISOString();let seqMeta=await db.meta.get('receiptSeq');let data={app:'ReciboCondo',backupFormat:3,settings:this.settings,providers:this.providers,services:this.services,receipts:this.receipts,recurrences:this.recurrences,payments:this.payments,logs:this.logs,receiptSeq:Number(seqMeta?.value||this.receiptMaxNumber()||0),backupStats:this.backupStats(),exportedAt:now};this.download('backup-recibocondo-prestadores.json',JSON.stringify(data,null,2),'application/json');this.backupLast=now;localStorage.setItem('rc_last_backup',now);await this.logAction('backup','Backup exportado','Backup JSON gerado com '+data.backupStats.records+' registros.')},"""
sub(r"async backup\(\)\{.*?\},(?=async restore\(ev\))",backup,'backup')

restore="""async restore(ev){let f=ev.target.files[0];if(!f)return;try{let data=JSON.parse(await f.text());if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('Backup inválido');let known=['settings','providers','services','receipts','recurrences','payments','logs','receiptSeq','backupStats','exportedAt','backupFormat','app'].some(k=>Object.prototype.hasOwnProperty.call(data,k));if(!known)throw new Error('O arquivo não parece ser um backup do ReciboCondo.');let providers=Array.isArray(data.providers)?data.providers:[],services=Array.isArray(data.services)?data.services:[],receipts=Array.isArray(data.receipts)?data.receipts:[],recurrences=Array.isArray(data.recurrences)?data.recurrences:[],payments=Array.isArray(data.payments)?data.payments:[],logs=Array.isArray(data.logs)?data.logs:[],duplicateIds=(arr)=>{let ids=arr.map(x=>x&&x.id).filter(x=>x!==undefined&&x!==null),set=new Set(ids.map(String));return set.size!==ids.length};if(duplicateIds(providers)||duplicateIds(services)||duplicateIds(receipts)||duplicateIds(recurrences)||duplicateIds(payments))throw new Error('O backup contém IDs duplicados e não será restaurado.');let providerIds=new Set(providers.map(x=>String(x?.id)).filter(x=>x!=='undefined'&&x!=='null')),serviceIds=new Set(services.map(x=>String(x?.id)).filter(x=>x!=='undefined'&&x!=='null'));let badService=services.find(x=>x?.providerId!==undefined&&x?.providerId!==null&&!providerIds.has(String(x.providerId)));if(badService)throw new Error('O backup contém lançamento sem prestador correspondente.');let badReceipt=receipts.find(x=>(x?.serviceId!==undefined&&x?.serviceId!==null&&!serviceIds.has(String(x.serviceId)))||(x?.providerId!==undefined&&x?.providerId!==null&&!providerIds.has(String(x.providerId))));if(badReceipt)throw new Error('O backup contém recibo sem lançamento ou prestador correspondente.');let badRecurrence=recurrences.find(x=>x?.providerId!==undefined&&x?.providerId!==null&&!providerIds.has(String(x.providerId)));if(badRecurrence)throw new Error('O backup contém recorrência sem prestador correspondente.');let badPayment=payments.find(x=>(x?.serviceId!==undefined&&x?.serviceId!==null&&!serviceIds.has(String(x.serviceId)))||(x?.providerId!==undefined&&x?.providerId!==null&&!providerIds.has(String(x.providerId))));if(badPayment)throw new Error('O backup contém pagamento sem lançamento ou prestador correspondente.');let total=providers.length+services.length+receipts.length+recurrences.length+payments.length+logs.length;if(!window.confirm('Restaurar este backup?\\n\\n'+providers.length+' prestador(es) • '+services.length+' lançamento(s) • '+receipts.length+' recibo(s) • '+payments.length+' pagamento(s) • '+recurrences.length+' recorrência(s)\\n\\nA base operacional atual será substituída.')){ev.target.value='';return}await db.transaction('rw',db.providers,db.services,db.receipts,db.recurrences,db.payments,db.logs,db.settings,db.meta,async()=>{await db.providers.clear();await db.services.clear();await db.receipts.clear();await db.recurrences.clear();await db.payments.clear();await db.logs.clear();if(data.settings){let restoredSettings=JSON.parse(JSON.stringify(data.settings));await db.settings.put({key:'main',value:restoredSettings});this.settings=restoredSettings}if(providers.length)await db.providers.bulkAdd(providers);if(services.length)await db.services.bulkAdd(services);if(receipts.length)await db.receipts.bulkAdd(receipts);if(recurrences.length)await db.recurrences.bulkAdd(recurrences);if(payments.length)await db.payments.bulkAdd(payments);if(logs.length)await db.logs.bulkAdd(logs.map(l=>{let x={...l};delete x.id;return x}).slice(0,200));let restoredMax=receipts.reduce((m,r)=>r.source==='Excel legado'?m:Math.max(m,Number(String(r.number||'').replace(/\\D/g,'')||0)),0),safeSeq=Math.max(Number(data.receiptSeq||0),restoredMax);await db.meta.put({key:'receiptSeq',value:safeSeq})});await this.logAction('restore','Backup restaurado','Dados restaurados por arquivo JSON • '+total+' registros validados.');await this.load();this.toast('Backup restaurado com sucesso!')}catch(e){console.error(e);this.toast('Não foi possível restaurar o backup: '+e.message,'error')}finally{ev.target.value=''}},"""
sub(r"async restore\(ev\)\{.*?\},(?=async clearAllInternal\(\))",restore,'restore')

clear_all="""async clearAllInternal(){await db.transaction('rw',db.providers,db.services,db.receipts,db.recurrences,db.payments,db.logs,async()=>{await db.providers.clear();await db.services.clear();await db.receipts.clear();await db.recurrences.clear();await db.payments.clear();await db.logs.clear()});this.selectedProviderId=null;this.currentReceipt=null;this.receiptServiceId='';this.paymentTarget=null;this.payModal=false;await this.load()},"""
sub(r"async clearAllInternal\(\)\{.*?\},(?=async clearAll\(\))",clear_all,'clear all')

p.write_text(s,encoding='utf-8')

sw=Path('sw.js')
w=sw.read_text(encoding='utf-8')
old="recibocondo-v100-integrity-cleanup"
new="recibocondo-v101-payment-ledger"
if w.count(old)!=1: raise SystemExit(f'sw cache: expected {old} once, got {w.count(old)}')
sw.write_text(w.replace(old,new,1),encoding='utf-8')

checks=['db.version(4).stores','payments:[]','ensurePaymentLedger()','db.payments.add','backupFormat:3','receiptId:null','get yearlyPaymentRows(){let y=','get reportDetailRows(){let rows=[]']
for c in checks:
    if c not in s: raise SystemExit('missing post-patch marker: '+c)
start=s.find("const db=new Dexie('ReciboCondoPrestadoresDB');")
end=s.find('</script>',start)
if start<0 or end<0: raise SystemExit('could not extract app script')
js=s[start:end]
with tempfile.NamedTemporaryFile('w',suffix='.js',delete=False,encoding='utf-8') as f:
    f.write(js); name=f.name
subprocess.run(['node','--check',name],check=True)
print('v101 patch OK; JS syntax valid')
